@startuml
[*] --> HumanDrivingMode : Power On

state HumanDrivingMode {
}

state AutonomousMode {
  [*] --> AutoNavigating
  AutoNavigating --> AutoFinal : Condition Met
}

HumanDrivingMode --> AutonomousMode : front_distance > 10
AutonomousMode --> HumanDrivingMode : Human Steering Cmd, Brake Pressed, in (AutoFinal)
[*] --> FinalState : Power Off
@enduml

@startuml
[*] --> PumpControl

state PumpControl {
    [*] --> InitialState

    state PumpState {
        [*] --> RunningState : Activate Pump
        RunningState --> [*] : Deactivate Pump
    }

    --

    state WaterState {
        [*] --> MonitoringWaterFlow : Start Monitoring
        MonitoringWaterFlow --> [*] : Stop Monitoring
    }

    --

    state MethaneState {
        [*] --> MonitoringMethaneFlow : Start Monitoring
        MonitoringMethaneFlow --> [*] : Stop Monitoring
    }


}
@enduml

@startuml
[*] --> PoweredOff

state Operate {
    [*] --> Idle
    Idle --> AcceleratingOrCruising : Accelerate Signal
    AcceleratingOrCruising --> Braking : Brake Signal
    Braking --> Idle : Stop Signal
}

PoweredOff --> Operate : start
Operate --> PoweredOff : keyOff
PoweredOff --> [*] : end

@enduml

@startuml
[*] --> DoorsClosing

state DoorsClosing {
  [*] --> DoorsClosing
}

DoorsClosing --> InMotion : Closed/SendDeparted

state InMotion {
  [*] --> Accelerating

  state Accelerating {
    Accelerating: entry/Accelerate
  }

  Accelerating --> Cruising : Reached Cruising/Cruise
  Accelerating --> Approaching : Approached/Decelerate

  state Cruising

  Cruising --> Approaching : Approached/Decelerate

  state Approaching {
    Approaching: do/Send
  }
}

InMotion --> Stopping : Arrived/Stop, Send Arrived
InMotion --> EmergencyStopping : Obstacle Detected

state EmergencyStopping {
  EmergencyStopping: entry/Emergency Stop
  EmergencyStopping: do/Send Obstacle Detected
}

state Stopping

@enduml

@startuml
[*] --> DoorShut

DoorShut : Cancel
DoorShut --> DoorOpen : Door Opened

DoorOpen --> DoorShut : Close Door
DoorOpen --> DoorOpenWithItem : Place Item Inside

state DoorOpenWithItem {
    [*] --> DoorIdleWithItem

    DoorIdleWithItem --> DoorOpen : Remove Item
    DoorIdleWithItem --> DoorShutWithItem : Close Door with Zero Time
    DoorIdleWithItem --> ReadytoCook : Enter Cooking Time
}

state DoorShutWithItem {
    [*] --> ItemInside

    ItemInside --> DoorOpenWithItem : Open Door
    ItemInside --> ReadytoCook : Enter Cooking Time
}

state ReadytoCook {
    [*] --> WaitingToStart

    WaitingToStart --> DoorShutWithItem : Cancel
    WaitingToStart --> DoorOpenWithItem : Open Door
    WaitingToStart --> Cooking : Start
}

state Cooking {
    [*] --> ActiveCooking

    ActiveCooking --> DoorOpenWithItem : Open Door
    ActiveCooking --> DoorShutWithItem : Timer Expired
    ActiveCooking --> ReadytoCook : Cancel
}
@enduml

@startuml
state "UAV Swarm State Machine" as UAVSwarmStateMachine {

[*] --> Searching
Searching : Target Search Task

Searching --> Intercepted : Interception Detected
Searching --> Attack : Task Assignment Received

state FormationAdjustment {
[*] --> AdjustingFormation
AdjustingFormation : Adjusting Formation after Interception
AdjustingFormation --> Searching : Adjustment Complete
}

state Attack {
[*] --> AttackingTarget
AttackingTarget : Performing Attack
AttackingTarget --> Searching : Attack Complete
}

Intercepted : UAV Swarm Intercepted
Intercepted --> FormationAdjustment

Attack : Entered Attack State
}
@enduml

@startuml
[*] --> TurnOn

state TurnOn {
[*] --> fork1: After (2 s)
}

TurnOn --> fork1
fork1 -down-> AutoFocus
fork1 -right-> DetLight

state AutoFocus {
[*] --> choice1: After (2 s)
choice1 --> Junction3: when (memFull=true)
}

state DetLight {
[*] --> choice2: After (1 s)
choice2 --> Join2: <<GaStep>>{prob=0.4}
choice2 --> Join1: [sunny=true]
}

fork1 -down-> choice3
choice3 --> ChargedFlash
ChargedFlash --> Junction3: when (Charged=true)

Junction3 --> Join2

state Join2 {
[*] --> Fork2
Fork2 --> Junction2
Fork2 --> Flash
Flash --> Terminate
}

Join1 --> Junction2

state Junction2 {
[*] --> TakePicture
TakePicture --> WriteMemory
WriteMemory --> Junction1
}

Junction1 --> TurnOff
TurnOff --> [*]
@enduml

@startuml
[*] --> Off
Off --> Operate : start
state Operate {
[*] --> Idle
Idle --> AcceleratingOrCruising : accelerate
AcceleratingOrCruising --> Braking : brake
Braking --> Idle : stop
}
Operate --> Off : keyOff
Off --> Terminate
Terminate : final
@enduml

@startuml
state DoorsClosing

DoorsClosing --> InMotion: Closed/SendDeparted

state InMotion {
[*] --> Accelerating : Entry/Accelerate
Accelerating --> Cruising : Reached Cruising/Cruise
Accelerating --> Approaching : Approached/Decelerate
Cruising --> Approaching : Approached/Decelerate

state Accelerating
state Cruising
state Approaching {
Approaching: Nearing Destination
Approaching: Ready to Stop/Decelerate
}
}

InMotion --> Stopping: Arrived/Stop, SendArrived
InMotion --> EmergencyStopping: Obstacle Detected

state Stopping
state EmergencyStopping {
Entry: Emergency Stop
EmergencyStopping: Obstacle Detected
}
@enduml

@startuml
[*] --> SearchMission : Start Mission

state SearchMission {
  [*] --> Region1

  state Region1 {
    [*] --> Search
    Search --> Region2 : Finished Region1 Search
  }

  state Region2 {
    [*] --> Search
    Search --> Region3 : Finished Region2 Search
  }

  state Region3 {
    [*] --> Search
    Search --> [*] : Finished Region3 Search
  }
}

SearchMission --> FormationAdjust : Interception Detected

state FormationAdjust {
  [*] --> AdjustingFormation
  AdjustingFormation --> SearchMission : Finish Adjusting
}

SearchMission --> AttackState : Task Assignment Received

state AttackState {
  [*] --> Attacking
  Attacking --> SearchMission : Attack Finished / Decrease UAV swarm count
}
@enduml

@startuml
[*] --> PumpControl
state PumpControl {
[*] --> PumpState
--
[*] --> WaterState
--
[*] --> MethaneState
PumpState: Pump Activated
WaterState: Water Flow Monitored
MethaneState: Methane Flow Monitored
}
@enduml

@startuml
[*] --> SearchingState
state SearchingState {
[*] --> TargetSearchingState
TargetSearchingState: Target Search State

TargetSearchingState --> FormationAdjustmentState : Intercepted
FormationAdjustmentState: Formation Adjustment State

TargetSearchingState --> AttackState : Task Assignment Received
AttackState: Attack State

AttackState --> TargetSearchingState : Attack Completed
TargetSearchingState --> [*] : Mission Completed
}
@enduml

@startuml
[*] --> HumanDriving : Power On

state HumanDriving {
}

state Autonomous {
state Navigating
state Parking
[*] --> Navigating
Navigating --> Parking : Park Request
Parking --> Navigating : Parking Complete
}

HumanDriving --> Autonomous : front_distance > 10
Autonomous --> HumanDriving : Human Steering Cmd / Brake Pressed / [*]

HumanDriving --> [*] : Power Off
@enduml

@startuml
[*] --> OffState
OffState : Off
OffState --> OperateState : start
OperateState : Operate

state OperateState {
[*] --> IdleRegion
state IdleRegion {
IdleState : Idle
}

state AccelerateRegion {
AcceleratingState : Accelerating
CruisingState : Cruising
}

state BrakeRegion {
BrakingState : Braking
}

IdleRegion --> AccelerateRegion : Accelerate
IdleRegion --> BrakeRegion : Brake
AccelerateRegion --> CruisingState : Reach Speed
AccelerateRegion --> BrakeRegion : Brake
CruisingState --> BrakeRegion : Brake
BrakeRegion --> IdleRegion : Stop
}

OperateState --> OffState : keyOff
@enduml

@startuml
[*] -down-> PumpControl : begin
PumpControl -down-> PumpState : Activate Pump
PumpControl -down-> WaterState : Monitor Water Flow
PumpControl -down-> MethaneState : Monitor Methane Flow

state PumpControl {
[*] --> PumpState
PumpState --> [*] : Pump Deactivated
}

state PumpControl {
[*] --> WaterState
WaterState --> [*] : Water Flow Stabilized
}

state PumpControl {
[*] --> MethaneState
MethaneState --> [*] : Methane Flow Stabilized
}
@enduml

@startuml
[*] --> InitialState
InitialState : Initial State

--

state Region1 {
[*] --> TargetSearch
TargetSearch : UAV Swarm Performing Target Search

TargetSearch --> FormationAdjustment : Interception Detected
FormationAdjustment : Adjusting Formation

FormationAdjustment --> TargetSearch : Formation Adjusted
}

--

state Region2 {
[*] --> AttackReady
AttackReady : Ready for Task Assignment

AttackReady --> Attack : Task Assignment Received
Attack : Engaging Target

Attack --> AttackReady : Attack Complete / UAV Count Decreased
}
@enduml

@startuml
[*] -down-> InitialState
InitialState: Initial State

state ActiveState {
[*] -down-> Inactive
Inactive: Inactive

Inactive -down-> FrontendCollision : Frontend Collision Detected
state FrontendCollisionRegion {
[*] -down-> BrakingControl
BrakingControl: Braking Control
BrakingControl -down-> Inactive : Collision Avoided
}

Inactive -down-> RearEndCollision : Rear-End Collision Detected
state RearEndCollisionRegion {
[*] -down-> SteeringControl
SteeringControl: Steering Control
SteeringControl -down-> Inactive : Collision Avoided
}

Inactive -down-> PedestrianCollision : Pedestrian Collision Detected
state PedestrianCollisionRegion {
[*] -down-> EmergencyStop
EmergencyStop: Emergency Stop
EmergencyStop -down-> Inactive : Collision Avoided
}
}

InitialState -up-> ActiveState : Collision Detected

@enduml

@startuml
[*] --> HumanDriving : Power On
HumanDriving : Human Driving Mode

HumanDriving --> Autonomous : front_distance > 10
state Autonomous {
[*] --> AutoInitial : Enter Autonomous Mode
AutoInitial --> AutoFinal : Auto Process Complete
AutoFinal : Auto Final State
}

Autonomous --> HumanDriving : human_steering_cmd || brake_pressed || in (AutoFinal)
HumanDriving --> [*] : Power Off
@enduml

@startuml
[*] --> Off : keyOff
Off --> Operate : start
Operate --> Off : keyOff

state Operate {
[*] --> Idle
Idle --> AcceleratingOrCruising : accelerate
AcceleratingOrCruising --> Idle : stop
AcceleratingOrCruising --> Braking : brake
Braking --> Idle : stop
Braking --> AcceleratingOrCruising : accelerate
}

@enduml

@startuml
[*] --> PumpControl

state PumpControl {
state "Region1" as Region1 {
[*] --> PumpState
PumpState --> WaterState : [Water Flow Detected]
PumpState --> MethaneState : [Methane Flow Detected]
WaterState --> PumpState : [Water Flow Completed]
MethaneState --> PumpState : [Methane Flow Completed]
}
--
state "Region2" as Region2 {
[*] --> Idle
Idle --> Active : [Activation Signal]
Active --> Idle : [Deactivation Signal]
}
}

@enduml

@startuml
state UAVSwarmStateMachine {
state SearchRegion {
[*] --> Idle
Idle : Initial State

Idle --> Searching : Start Mission
Searching : Target Search State
Searching --> FormationAdjustment : Intercepted
Searching --> Attacking : Task Assignment Received

FormationAdjustment : Formation Adjustment State
FormationAdjustment --> Searching : Formation Adjusted

Attacking : Attack State
Attacking --> Searching : Attack Completed / UAV Count Decreased
}

state MissionRegion {
[*] --> MissionActive
MissionActive : Mission Active State
MissionActive --> MissionComplete : Mission Completed
MissionComplete : Mission Complete State
}
}

SearchRegion --> MissionRegion : Mission Completed
MissionRegion --> SearchRegion : Start Mission

@enduml

@startuml
state CollisionAvoidanceSystem {
state "Frontend Collision Avoidance" as Frontend {
[*] --> Idle
Idle --> Braking : Collision Detected
Braking --> Clamping : Brake Applied
Clamping --> Idle : Collision Avoided
}

state "Rear-End Collision Avoidance" as RearEnd {
[*] --> Idle
Idle --> Braking : Collision Detected
Braking --> Clamping : Brake Applied
Clamping --> Idle : Collision Avoided
}

state "Pedestrian Collision Avoidance" as Pedestrian {
[*] --> Idle
Idle --> Braking : Collision Detected
Braking --> Clamping : Brake Applied
Clamping --> Idle : Collision Avoided
}
}

[*] --> CollisionAvoidanceSystem
CollisionAvoidanceSystem --> [*] : Collision Avoided

@enduml

@startuml

[*] --> HumanDrivingMode : Power On

state HumanDrivingMode {
}

state AutonomousMode {
[*] --> SubState1
SubState1 --> SubState2
SubState2 --> SubState3
SubState3 --> [*]
}

HumanDrivingMode --> AutonomousMode : [front_distance > 10]

AutonomousMode --> HumanDrivingMode : human steering cmd\nor brake pressed\nor in (auto final)

HumanDrivingMode --> [*] : Power Off
AutonomousMode --> [*] : Power Off

@enduml

@startuml

[*] --> Off
Off --> Operate : start

state Operate {
[*] --> Idle
Idle --> Accelerating_or_Cruising : accelerate
Accelerating_or_Cruising --> Braking : brake
Braking --> Idle : stop
Accelerating_or_Cruising --> Idle : stop
}

Operate --> Off : keyOff
Off --> [*] : shutdown

@enduml

@startuml

[*] --> PumpControl

state PumpControl {
state PumpRegion {
[*] --> PumpState
PumpState : Pump activated or controlled
}

state WaterRegion {
[*] --> WaterState
WaterState : Water flow control/monitoring
}

state MethaneRegion {
[*] --> MethaneState
MethaneState : Methane flow control/monitoring
}
}

@enduml

@startuml
state "Collision Avoidance" as CA {
state Frontend {
[*] --> FCIdle
FCIdle --> FCActive : Frontend collision detected
FCActive --> FCIdle : Collision avoided
}

state RearEnd {
[*] --> RCIdle
RCIdle --> RCActive : Rear-end collision detected
RCActive --> RCIdle : Collision avoided
}

state Pedestrian {
[*] --> PCIdle
PCIdle --> PCActive : Pedestrian collision detected
PCActive --> PCIdle : Collision avoided
}
}

[*] --> CA : Possible collision detected
@enduml

@startuml

state TurnOn {
state ""TurnOn"" as TurnOn_state
}
TurnOn_state : {max=2s, min=2s}

[*] --> TurnOn_state
TurnOn_state --> fork1

state fork1 <<fork>>
fork1 --> AutoFocus
fork1 --> DetLight
fork1 --> choice3

state AutoFocus {
state ""AutoFocus"" as AutoFocus_state
}
AutoFocus_state : {max=2s, min=1s}

AutoFocus_state --> choice1 : [memFull=true]

state DetLight {
state ""DetLight"" as DetLight_state
}
DetLight_state : {max=1s, min=0s}

DetLight_state --> choice2 : <<GaStep>>{prob=0.4}

state ChargedFlash {
state ""ChargedFlash"" as ChargedFlash_state
}
ChargedFlash_state : {max=4s, min=2s}

choice3 --> ChargedFlash_state
ChargedFlash_state --> Junction3 : [Charged=true]
choice3 --> Junction3

state Join2 <<join>>
Junction3 --> Join2

choice2 --> Join2
choice2 --> Join1 : [sunny=true]

state Join1 <<join>>
Join1 --> Junction2

Junction2 --> TakePicture
TakePicture --> WriteMemory
state WriteMemory {
state ""WriteMemory"" as WriteMemory_state
}
WriteMemory_state : {max=3s, min=2s}

WriteMemory_state --> Junction1
Junction1 --> TurnOff
TurnOff --> [*]

state Join2 {
state fork2 <<fork>>
fork2 --> Junction2
fork2 --> Flash
}

Flash --> Terminate

@enduml"
